#include <format>
#include <iostream>
#include <memory>
#include <string>
#include <string_view>

struct Tracer {
  explicit Tracer(std::string_view n) : name(n) { std::cout << std::format("make {}\n", name); }
  ~Tracer() { std::cout << std::format("drop {}\n", name); }
  Tracer(const Tracer&) = delete;
  Tracer& operator=(const Tracer&) = delete;
  Tracer(Tracer&&) = delete;
  Tracer& operator=(Tracer&&) = delete;

  const std::string name;
};

const Tracer global("global");

Tracer make(std::string_view name) { return Tracer(name); }

void f() {
  static const Tracer once("static in f");
  const Tracer local("local in f");
}

int main() {
  std::cout << "main starts\n";
  const Tracer a("a");
  f();
  f();
  auto heap = std::make_unique<Tracer>("heap");
  make("temporary");
  const Tracer& kept = make("kept by const&");
  std::cout << std::format("using {}\n", kept.name);
  heap.reset();
  std::cout << "main ends\n";
}

