#include <format>
#include <iostream>
#include <vector>

[[nodiscard]] int next_id() {
  static int counter = 0;  // static: one object for the whole program
  return ++counter;
}

struct Scan {
  int id;
  std::vector<int> ranges_mm;  // owns its elements, which live in dynamic storage
};

// One compiled function serves every beam count, so the size is known only at run time.
[[nodiscard]] Scan read_scan(int beams) {
  return Scan{.id = next_id(), .ranges_mm = std::vector<int>(beams, 1000)};
}

int main() {
  for (const int beams : {360, 720, 1080}) {
    const Scan scan = read_scan(beams);  // automatic: a new Scan on every pass
    std::cout << std::format("scan {}: {} ranges\n", scan.id, std::ssize(scan.ranges_mm));
  }
}

#include <array>
#include <format>
#include <iostream>
#include <thread>

[[nodiscard]] int& counter() {
  static int value = 0;  // made on the first call, lives until after main
  return value;
}

int count_call() {
  thread_local int calls = 0;  // a separate object in every thread
  return ++calls;
}

int main() {
  ++counter();
  ++counter();
  ++counter();
  std::cout << std::format("counter {}\n", counter());

  std::array<int, 2> seen{};
  {
    const std::jthread a([&seen] {
      count_call();
      seen[0] = count_call();
    });
    const std::jthread b([&seen] { seen[1] = count_call(); });
  }  // b is joined and destroyed here, then a
  std::cout << std::format("thread a saw {}, thread b saw {}, main sees {}\n", seen[0], seen[1], count_call());
}

