class Base {
 public:
  Base() { std::cout << "  Base body\n"; }

 protected:
  ~Base() { std::cout << "  ~Base body\n"; }  // protected: nothing destroys a Robot through a Base*

 private:
  Tracer engine_{"Base::engine"};
};

class Robot : public Base {
 public:
  Robot() : left_("Robot::left"), right_("Robot::right") { std::cout << "  Robot body\n"; }
  ~Robot() { std::cout << "  ~Robot body\n"; }

 private:
  Tracer left_;
  Tracer right_;
};

int main() {
  std::cout << "build:\n";
  {
    const Robot r;
    std::cout << "destroy:\n";
  }
}

struct Window {
  int area;   // declared first, so initialised first
  int width;
  explicit Window(int w) : width(w), area(width * width) {}  // reads width before it is set
};

int main() {
  const Window w(3);
  return w.area;
}

