#include <string>

[[nodiscard]] std::string make_name() { return "robot-7"; }
[[nodiscard]] const std::string make_const_name() { return "robot-7"; }

struct View {
  const std::string& name;
  explicit View(const std::string& n) : name(n) {}
  View(const std::string&&) = delete;  // every temporary, const or not, picks this overload and fails
};

int main() {
  const View v(make_name());
  const View w(make_const_name());
  return static_cast<int>(v.name.size() + w.name.size());
}

